import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import axios from 'axios';
import './Category.css';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const categoryMeta = {
  dry: {
    title: 'Dry Items (Namkeen & Farsan)',
    icon: '🥨',
    desc: 'Crispy, crunchy savory snacks perfect for any time of the day. All our dry items are prepared fresh and have a longer shelf life.',
    color: '#D44444',
    bgGradient: 'linear-gradient(135deg, #FFF5E6, #FFE8CC)'
  },
  sweet: {
    title: 'Sweet Items (Longer Shelf Life)',
    icon: '🍬',
    desc: 'Traditional Maharashtrian sweets that stay fresh longer. Perfect for gifting and celebrations.',
    color: '#FF6B35',
    bgGradient: 'linear-gradient(135deg, #FFF0E6, #FFE0CC)'
  },
  wet: {
    title: 'Wet/Fresh Sweets (Shorter Shelf Life)',
    icon: '🍮',
    desc: 'Freshly made premium sweets, best consumed within days. These require advance booking for guaranteed freshness.',
    color: '#8B4513',
    bgGradient: 'linear-gradient(135deg, #FFF8F0, #FFEDD5)'
  }
};

function Category({ addToCart }) {
  const { category } = useParams();
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [addedMsg, setAddedMsg] = useState('');

  const meta = categoryMeta[category] || {
    title: 'Our Products',
    icon: '🛍️',
    desc: 'Browse our collection',
    color: '#8B0000',
    bgGradient: 'linear-gradient(135deg, #FFF5E6, #FFE8CC)'
  };

  useEffect(() => {
    fetchProducts();
  }, [category]);

  const fetchProducts = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API_URL}/api/products/?category=${category}`);
      setProducts(res.data.products);
    } catch (err) {
      console.error('Error fetching products:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleAddToCart = (product) => {
    addToCart(product);
    setAddedMsg(product.name);
    setTimeout(() => setAddedMsg(''), 2000);
  };

  if (loading) {
    return (
      <div className="category-loading">
        <div className="spinner"></div>
        <p>Loading products...</p>
      </div>
    );
  }

  return (
    <div className="category-page">
      {/* Category Header */}
      <div className="category-header" style={{ background: meta.bgGradient }}>
        <div className="container">
          <div className="category-header-content">
            <Link to="/" className="breadcrumb">
              ← Back to Home
            </Link>
            <div className="category-title-wrap">
              <span className="category-header-icon">{meta.icon}</span>
              <div>
                <h1 className="category-title">{meta.title}</h1>
                <p className="category-desc">{meta.desc}</p>
              </div>
            </div>
            {category === 'wet' && (
              <div className="advance-booking-banner">
                <span>⏰</span>
                <span>Fresh sweets require 1-2 days advance booking</span>
              </div>
            )}
            <div className="category-stats">
              <span className="category-stat">
                <strong>{products.length}</strong> items available
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* Products Grid */}
      <div className="container category-products">
        {products.length === 0 ? (
          <div className="no-products">
            <span className="no-products-icon">📭</span>
            <h3>No products found in this category</h3>
            <p>Please check back later or explore other categories</p>
            <Link to="/" className="btn btn-primary">Back to Home</Link>
          </div>
        ) : (
          <div className="category-grid">
            {products.map(product => (
              <div key={product._id} className="product-card card">
                <div className="product-image">
                  <div className="product-image-placeholder" style={{ background: meta.bgGradient }}>
                    <span className="product-emoji">{meta.icon}</span>
                  </div>
                  {!product.is_regular && (
                    <span className="product-badge">Advance Booking</span>
                  )}
                </div>
                <div className="product-details">
                  <h3 className="product-name">{product.name}</h3>
                  <p className="product-desc">{product.description}</p>
                  <div className="product-meta">
                    <span className="product-price">₹{product.price}/{product.unit}</span>
                    {product.is_regular ? (
                      <span className="badge badge-primary">In Stock</span>
                    ) : (
                      <span className="badge badge-warning">On Order</span>
                    )}
                  </div>
                  <button
                    className="btn btn-primary add-to-cart-btn"
                    onClick={() => handleAddToCart(product)}
                  >
                    🛒 Add to Cart
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Delivery Info Bar */}
      <div className="delivery-info-bar">
        <div className="container delivery-info-content">
          <div className="delivery-info-item">
            <span>🚚</span>
            <span>Free delivery above ₹300</span>
          </div>
          <div className="delivery-info-item">
            <span>📅</span>
            <span>Next-day delivery for regular items</span>
          </div>
          <div className="delivery-info-item">
            <span>💳</span>
            <span>COD & UPI payments accepted</span>
          </div>
        </div>
      </div>

      {/* Toast */}
      {addedMsg && (
        <div className="toast-notification">
          <span>✅</span> {addedMsg} added to cart!
        </div>
      )}
    </div>
  );
}

export default Category;
